type DocChangeSet = {
  id: string;
  summary: string;
  status: "open" | "applied" | "declined";
  sessionId?: string;
  annotationId?: string;
  alias?: string;
  entries: Array<{ docPath: string; proposalId: string }>;
  treeOps: Array<
    | { kind: "create-doc"; docPath: string; title: string }
    | { kind: "delete-doc"; docPath: string }
    | { kind: "move-doc"; from: string; to: string }
  >;
  createdAt: string;
  resolvedAt?: string;
};
